import {treemapLayout} from './treemap.js';
import {escapeHtml as esc} from './components.js';
import {pct,ret,dollars} from './crypto-format.js';
function color(v){if(!Number.isFinite(v))return 'repeating-linear-gradient(135deg,#f1f4f7,#f1f4f7 5px,#fff 5px,#fff 10px)';return v===0?'#edf0f4':`rgba(${v>0?'216,75,82':'52,121,212'},${.14+.55*Math.min(Math.abs(v)/10,1)})`;}
export function renderCryptoMap(root,items,period,focus=null,scale=1,area='cap',quoteFormat=null){
 const isVolume=area==='volume',eligible=isVolume?items.filter(c=>c.quoteVolume>0&&Number.isFinite(ret(c,period))).map(c=>({...c,originalCap:c.marketCap,marketCap:c.quoteVolume})):items;
 const selected=focus?eligible.filter(c=>isVolume?c.primary.id===focus:c.primary.id===focus||c.categories.some(s=>s.id===focus)).map(c=>({...c,primary:c.categories.find(s=>s.id===focus)||c.primary})):eligible,withCap=selected.filter(c=>c.marketCap>0),without=selected.filter(c=>!(c.marketCap>0));const grouped=new Map();
 for(const c of withCap){const group=grouped.get(c.primary.id)||{...c.primary,marketCap:0,coins:[]};group.marketCap+=c.marketCap;group.coins.push(c);grouped.set(c.primary.id,group);}
 const width=root.clientWidth||650,height=root.closest('dialog')?Math.max(420,innerHeight-240):420,groups=treemapLayout([...grouped.values()],0,0,100,100,width/height);
 root.innerHTML=`<div class="crypto-map-canvas" style="height:${height*scale}px;min-width:${scale*100}%">${groups.map(g=>{const insetW=(g.w/100*width),insetH=g.h/100*height-23,tiles=treemapLayout(g.coins.map(c=>({...c,id:String(c.id)})),0,0,100,100,insetW/Math.max(1,insetH));return `<section class="crypto-map-group" style="left:${g.x}%;top:${g.y}%;width:${g.w}%;height:${g.h}%"><button class="crypto-map-title" data-map-sector="${esc(g.id)}" title="${esc(g.label)} 확대">${esc(g.label)}</button><div class="crypto-map-tiles">${tiles.map(c=>{const big=c.w/100*insetW*scale>48&&c.h/100*insetH*scale>28;return `<button class="crypto-map-coin ${big?'':'tiny'}" data-coin="${esc(c.id)}" style="left:${c.x}%;top:${c.y}%;width:${c.w}%;height:${c.h}%;background:${color(ret(c,period))}" title="${esc(c.name)} · ${esc(c.symbol)} · ${pct(ret(c,period))} · ${isVolume?'24시간 거래대금':'시총'} ${esc(isVolume&&quoteFormat?quoteFormat(c.marketCap):dollars(c.marketCap,true).replace('$','')+(isVolume?' USDT':' USD'))}" aria-label="${esc(c.name)} ${pct(ret(c,period))} 상세"><b>${esc(c.symbol)}</b><span>${pct(ret(c,period))}</span></button>`;}).join('')}</div></section>`;}).join('')}${!groups.length?'<div class="crypto-empty">선택 기간을 계산할 수 있는 코인이 없습니다.</div>':''}</div>${without.length?`<div class="crypto-map-unscaled"><small>시가총액 없음 · 동일 크기 · ${without.length}개</small><div>${without.map(c=>`<button data-coin="${esc(c.id)}" style="background:${color(ret(c,period))}" title="${esc(c.name)} · ${c.primary.label}">${esc(c.symbol)} <span>${pct(ret(c,period))}</span></button>`).join('')}</div></div>`:''}`;
}

